# Text Reshaping for Arabic
try:
    import arabic_reshaper
    from bidi.algorithm import get_display
    HAS_ARABIC_SUPPORT = True
except ImportError:
    HAS_ARABIC_SUPPORT = False
    print("Warning: arabic-reshaper or python-bidi not installed. Arabic text may be disjointed.")

def fix_text(text):
    """Reshapes Arabic text to fix disjointed characters and direction."""
    if not HAS_ARABIC_SUPPORT or not text:
        return text
    try:
        reshaped_text = arabic_reshaper.reshape(text)
        return get_display(reshaped_text)
    except:
        return text

class ModernTheme:
    """Configures colors and styles for a modern look"""
    
    # Color Palette (Modern & Professional)
    COLORS = {
        "bg_main": "#f0f2f5",         # Light Grey Background
        "bg_card": "#ffffff",         # White Cards
        "primary": "#2196F3",         # Material Blue
        "primary_dark": "#1976D2",    # Darker Blue
        "success": "#4CAF50",         # Green
        "error": "#F44336",           # Red
        "text_main": "#333333",       # Dark Grey Text
        "text_light": "#757575",      # Light Grey Text
        "log_bg": "#1e1e1e",          # Dark Terminal
        "log_fg": "#4caf50",          # Terminal Green
        "input_bg": "#f8f9fa"         # Very light grey for inputs
    }

    @staticmethod
    def apply(root):
        style = ttk.Style()
        try:
            style.theme_use('clam')
        except:
            pass # Fallback to default if clam not available

        c = ModernTheme.COLORS
        
        # General configurations
        style.configure(".", background=c["bg_main"], foreground=c["text_main"])
        
        # Cards (Frames with white background)
        style.configure("Card.TFrame", background=c["bg_card"], relief="flat")
        
        # LabelFrames
        style.configure("TLabelframe", background=c["bg_card"], foreground=c["primary_dark"])
        style.configure("TLabelframe.Label", background=c["bg_card"], foreground=c["text_main"], font=("Helvetica", 10, "bold"))
        
        # Labels
        style.configure("TLabel", background=c["bg_card"], foreground=c["text_main"], font=("Helvetica", 10))
        style.configure("Header.TLabel", background=c["bg_main"], foreground=c["text_main"], font=("Segoe UI", 16, "bold"))
        style.configure("SubLabel.TLabel", background=c["bg_card"], foreground=c["text_light"], font=("Helvetica", 9))
        
        # Buttons
        style.configure("TButton", 
            padding=10, 
            relief="flat", 
            background=c["primary"], 
            foreground="white",
            font=("Helvetica", 10, "bold")
        )
        style.map("TButton",
            background=[("active", c["primary_dark"]), ("disabled", "#bdc3c7")],
            foreground=[("disabled", "#ecf0f1")]
        )
        
        # Accent Button (Green)
        style.configure("Success.TButton", background=c["success"])
        style.map("Success.TButton", background=[("active", "#388E3C")])

        # Entries and Comboboxes
        style.configure("TEntry", fieldbackground=c["input_bg"], padding=5, borderwidth=1, relief="solid")
        style.configure("TCombobox", fieldbackground=c["input_bg"], padding=5)

        # Progress Bar
        style.configure("Horizontal.TProgressbar", background=c["primary"], troughcolor="#e0e0e0", borderwidth=0)
        
        return c

class VideoTranslatorGUI:
    def __init__(self, root):
        self.root = root
        self.root.title(fix_text("Video Translator Pro - المترجم الذكي"))
        self.root.geometry("900x750")
        self.root.minsize(800, 600)
        
        # Apply Theme
        self.colors = ModernTheme.apply(root)
        self.root.configure(bg=self.colors["bg_main"])
        
        # Setup Fonts
        self.setup_fonts()
        
        # Variables
        self.video_path = tk.StringVar()
        self.video_url = tk.StringVar()  # Video URL for downloading
        self.output_path = tk.StringVar()
        self.batch_size = tk.IntVar(value=vt.BATCH_SIZE)
        self.keep_audio = tk.BooleanVar(value=False)
        self.target_lang = tk.StringVar(value="Arabic")
        self.embed_subs = tk.BooleanVar(value=False)
        self.initial_prompt = tk.StringVar()  # Context/keywords for Whisper
        self.download_speed = tk.IntVar(value=0)  # Download speed limit (0 = unlimited)
        self.download_quality = tk.StringVar(value="720p")  # Download quality preset
        self.content_profile = tk.StringVar(value=vt.DEFAULT_PROFILE)  # Smart Content Profile
        self.use_vocal_isolation = tk.BooleanVar(value=False)  # Professional vocal isolation
        self.download_only = tk.BooleanVar(value=False)  # Download only mode (skip translation)
        self.is_running = False
        
        # Setup UI
        self.setup_ui()
        
        # Segment data storage for editor
        self.segments_data = []  # List of {idx, start, end, original, text}
        self.current_srt_path = None
        self.original_segments = []  # Store original transcription for comparison
        
    def setup_fonts(self):
        """Setup fonts with Arabic support."""
        available_fonts = tkfont.families()
        arabic_fonts = [
            "Segoe UI", "Tahoma", "Noto Sans Arabic", "DejaVu Sans", 
            "Arial", "Microsoft Sans Serif"
        ]
        
        self.main_font = "TkDefaultFont"
        for font in arabic_fonts:
            if font in available_fonts:
                self.main_font = font
                break
                
        default_font = tkfont.nametofont("TkDefaultFont")
        default_font.configure(family=self.main_font, size=10)
        self.root.option_add("*Font", default_font)

    def setup_ui(self):
        """Setup the User Interface with Cards"""
        
        # Container
        container = ttk.Frame(self.root, padding="20")
        container.pack(fill=tk.BOTH, expand=True)
        
        # Header
        header = ttk.Label(container, text=fix_text("Video Translator | مترجم الفيديو"), style="Header.TLabel")
        header.pack(fill=tk.X, pady=(0, 20))
        
        # === Left Column: Input/Output ===
        # We'll use a PanedWindow or just split frames. Let's do simple top-down for reliability across resize.
        
        # Card 1: Configuration
        config_card = ttk.LabelFrame(container, text=fix_text(" Configuration / الإعدادات "), padding="20")
        config_card.pack(fill=tk.X, pady=(0, 15))
        
        # Row 0: Video URL (for downloading)
        url_frame = ttk.Frame(config_card, style="Card.TFrame")
        url_frame.pack(fill=tk.X, pady=(0, 10))
        
        url_labels = ttk.Frame(url_frame, style="Card.TFrame")
        url_labels.pack(fill=tk.X)
        ttk.Label(url_labels, text="Video URL:", font=("Helvetica", 10, "bold")).pack(side=tk.LEFT)
        ttk.Label(url_labels, text=fix_text("رابط الفيديو (YouTube, غيره)"), font=("Helvetica", 10), foreground=self.colors["primary"]).pack(side=tk.RIGHT)
        
        url_input_frame = ttk.Frame(url_frame, style="Card.TFrame")
        url_input_frame.pack(fill=tk.X, pady=(5, 0))
        url_entry = ttk.Entry(url_input_frame, textvariable=self.video_url)
        url_entry.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 10))
        
        # Quality selector
        quality_frame = ttk.Frame(url_input_frame, style="Card.TFrame")
        quality_frame.pack(side=tk.RIGHT, padx=(0, 15))
        ttk.Label(quality_frame, text=fix_text("الجودة:"), font=("Helvetica", 9)).pack(side=tk.LEFT, padx=(0, 5))
        quality_combo = ttk.Combobox(quality_frame, textvariable=self.download_quality, 
                                      values=list(vt.DOWNLOAD_QUALITIES.keys()), state="readonly", width=10)
        quality_combo.pack(side=tk.LEFT)
        quality_combo.set("720p")
        
        # Speed limit slider
        speed_frame = ttk.Frame(url_input_frame, style="Card.TFrame")
        speed_frame.pack(side=tk.RIGHT)
        ttk.Label(speed_frame, text=fix_text("السرعة:"), font=("Helvetica", 9)).pack(side=tk.LEFT, padx=(0, 5))
        self.speed_label = ttk.Label(speed_frame, text="∞", font=("Helvetica", 9, "bold"), width=8)
        self.speed_label.pack(side=tk.RIGHT, padx=(5, 0))
        speed_scale = ttk.Scale(speed_frame, from_=0, to=5000, variable=self.download_speed, orient=tk.HORIZONTAL, length=100, command=self.update_speed_label)
        speed_scale.pack(side=tk.LEFT)
        
        ttk.Label(url_frame, text=fix_text("(Paste URL to download or leave empty to use local file / الصق الرابط للتحميل أو اتركه فارغاً لاستخدام ملف محلي)"), style="SubLabel.TLabel").pack(anchor="w")
        
        # Separator
        ttk.Separator(config_card, orient=tk.HORIZONTAL).pack(fill=tk.X, pady=10)
        
        # Row 1: Video File
        self.create_file_input(config_card, "Video File:", fix_text("ملف الفيديو"), self.video_path, self.browse_video, 0)
        
        # Row 2: Settings (Grid inside card)
        settings_frame = ttk.Frame(config_card, style="Card.TFrame")
        settings_frame.pack(fill=tk.X, pady=10)
        
        # Target Language
        lang_frame = ttk.Frame(settings_frame, style="Card.TFrame")
        lang_frame.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 10))
        ttk.Label(lang_frame, text=fix_text("Target Language / اللغة الهدف")).pack(anchor="w")
        lang_combo = ttk.Combobox(lang_frame, textvariable=self.target_lang, values=list(vt.HELSINKI_LANGUAGES.keys()), state="readonly")
        lang_combo.pack(fill=tk.X, pady=5)
        lang_combo.set("Arabic")
        
        # Batch Size
        batch_frame = ttk.Frame(settings_frame, style="Card.TFrame")
        batch_frame.pack(side=tk.LEFT, padx=10)
        ttk.Label(batch_frame, text="Batch Size").pack(anchor="w")
        ttk.Spinbox(batch_frame, from_=1, to=64, textvariable=self.batch_size, width=8).pack(pady=5)

        # Options (Checkboxes)
        opts_frame = ttk.Frame(settings_frame, style="Card.TFrame")
        opts_frame.pack(side=tk.LEFT, padx=20)
        ttk.Checkbutton(opts_frame, text=fix_text("Embed Subtitles (دمج الترجمة)"), variable=self.embed_subs).pack(anchor="w")
        ttk.Checkbutton(opts_frame, text=fix_text("Keep Audio (حفظ الصوت)"), variable=self.keep_audio).pack(anchor="w")
        
        # Advanced Audio Options
        audio_opts_frame = ttk.Frame(settings_frame, style="Card.TFrame")
        audio_opts_frame.pack(side=tk.LEFT, padx=20)
        vocal_cb = ttk.Checkbutton(audio_opts_frame, text=fix_text("🎤 Vocal Isolation (UVR5)"), variable=self.use_vocal_isolation)
        vocal_cb.pack(anchor="w")
        ttk.Checkbutton(audio_opts_frame, text=fix_text("⬇️ Download Only (تنزيل فقط)"), variable=self.download_only).pack(anchor="w")

        # Row 2.5: Content Profile Selector
        profile_section = ttk.Frame(config_card, style="Card.TFrame")
        profile_section.pack(fill=tk.X, pady=(10, 5))
        
        profile_labels = ttk.Frame(profile_section, style="Card.TFrame")
        profile_labels.pack(fill=tk.X)
        ttk.Label(profile_labels, text="Content Profile:", font=("Helvetica", 10, "bold")).pack(side=tk.LEFT)
        ttk.Label(profile_labels, text=fix_text("نوع المحتوى"), font=("Helvetica", 10), foreground=self.colors["primary"]).pack(side=tk.RIGHT)
        
        profile_combo = ttk.Combobox(profile_section, textvariable=self.content_profile,
                                      values=list(vt.CONTENT_PROFILES.keys()), state="readonly", width=25)
        profile_combo.pack(anchor="w", pady=(5, 0))
        profile_combo.set(vt.DEFAULT_PROFILE)
        
        # Profile description label
        self.profile_desc_label = ttk.Label(profile_section, text="", style="SubLabel.TLabel")
        self.profile_desc_label.pack(anchor="w")
        self.update_profile_description(None)
        profile_combo.bind("<<ComboboxSelected>>", self.update_profile_description)

        # Row 3: Initial Prompt (Context/Keywords)
        prompt_frame = ttk.Frame(config_card, style="Card.TFrame")
        prompt_frame.pack(fill=tk.X, pady=(10, 5))
        
        prompt_labels = ttk.Frame(prompt_frame, style="Card.TFrame")
        prompt_labels.pack(fill=tk.X)
        ttk.Label(prompt_labels, text="Content Prompt:", font=("Helvetica", 10, "bold")).pack(side=tk.LEFT)
        ttk.Label(prompt_labels, text=fix_text("كلمات مفتاحية / وصف المحتوى"), font=("Helvetica", 10), foreground=self.colors["primary"]).pack(side=tk.RIGHT)
        
        prompt_entry = ttk.Entry(prompt_frame, textvariable=self.initial_prompt)
        prompt_entry.pack(fill=tk.X, pady=(5, 0))
        ttk.Label(prompt_frame, text=fix_text("(Optional: Enter keywords or context to improve transcription / اختياري: أدخل كلمات مفتاحية أو سياق لتحسين النسخ)"), style="SubLabel.TLabel").pack(anchor="w")

        # Row 3: Output (Optional)
        # Hidden by default or subtle, usually auto-generated is fine, but let's show it concisely
        out_frame = ttk.Frame(config_card, style="Card.TFrame")
        out_frame.pack(fill=tk.X, pady=(10, 0))
        ttk.Label(out_frame, text="Output SRT (Optional):", style="SubLabel.TLabel").pack(side=tk.LEFT)
        ttk.Entry(out_frame, textvariable=self.output_path).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=10)
        ttk.Button(out_frame, text="...", width=3, command=self.browse_output).pack(side=tk.LEFT)

        # === Action Bar ===
        action_frame = ttk.Frame(container)
        action_frame.pack(fill=tk.X, pady=(0, 15))
        
        self.start_btn = ttk.Button(action_frame, text=fix_text("▶ START TRANSLATION / بدء الترجمة"), style="Success.TButton", command=self.start_translation)
        self.start_btn.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 10))
        
        self.stop_btn = ttk.Button(action_frame, text="■ STOP", command=self.stop_translation, state=tk.DISABLED)
        self.stop_btn.pack(side=tk.RIGHT)

        # === Progress & Logs ===
        log_card = ttk.LabelFrame(container, text=fix_text(" Process Logs / سير العمليات "), padding="10")
        log_card.pack(fill=tk.BOTH, expand=True)

        # Progress Bar
        self.progress_bar = ttk.Progressbar(log_card, mode='indeterminate', style="Horizontal.TProgressbar")
        self.progress_bar.pack(fill=tk.X, pady=(0, 10))
        
        # Status Text
        self.status_label = ttk.Label(log_card, text="Ready to start...", font=("Helvetica", 10, "italic"))
        self.status_label.pack(anchor="w", pady=(0, 5))

        # Terminal Log
        self.log_text = scrolledtext.ScrolledText(
            log_card, 
            height=10,
            bg=self.colors["log_bg"],
            fg=self.colors["log_fg"],
            insertbackground="white", # cursor color
            font=("Consolas", 10),
            relief="flat",
            state=tk.DISABLED
        )
        self.log_text.pack(fill=tk.BOTH, expand=True)
        
        # Footer
        footer = ttk.Frame(container)
        footer.pack(fill=tk.X, pady=(10, 0))
        ttk.Button(footer, text="Clear Log", command=self.clear_log).pack(side=tk.RIGHT)
        ttk.Button(footer, text=fix_text("Open Editor / المحرر"), command=self.show_editor).pack(side=tk.RIGHT, padx=5)
        ttk.Label(footer, text="Video Translator v3.0 (Enhanced)", style="SubLabel.TLabel").pack(side=tk.LEFT)

    def create_file_input(self, parent, label_en, label_ar, variable, command, pady):
        frame = ttk.Frame(parent, style="Card.TFrame")
        frame.pack(fill=tk.X, pady=pady)
        
        labels_frame = ttk.Frame(frame, style="Card.TFrame")
        labels_frame.pack(fill=tk.X)
        ttk.Label(labels_frame, text=label_en, font=("Helvetica", 10, "bold")).pack(side=tk.LEFT)
        ttk.Label(labels_frame, text=label_ar, font=("Helvetica", 10), foreground=self.colors["primary"]).pack(side=tk.RIGHT)
        
        input_frame = ttk.Frame(frame, style="Card.TFrame")
        input_frame.pack(fill=tk.X, pady=(5, 0))
        
        entry = ttk.Entry(input_frame, textvariable=variable)
        entry.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 10))
        
        btn = ttk.Button(input_frame, text="Browse 📂", command=command)
        btn.pack(side=tk.RIGHT)

    def browse_video(self):
        filetypes = [("Video Files", "*.mp4 *.mkv *.avi *.mov *.webm *.flv"), ("All Files", "*.*")]
        path = filedialog.askopenfilename(title="Select Video", filetypes=filetypes)
        if path:
            self.video_path.set(path)
            # Auto-set output
            stem = Path(path).stem
            parent = Path(path).parent
            self.output_path.set(str(parent / f"{stem}_ar.srt"))
            
    def browse_output(self):
        path = filedialog.asksaveasfilename(title="Save SRT", filetypes=[("Subtitle", "*.srt")], defaultextension=".srt")
        if path:
            self.output_path.set(path)

    def log(self, message):
        self.log_text.config(state=tk.NORMAL)
        self.log_text.insert(tk.END, f"> {message}\n")
        self.log_text.see(tk.END)
        self.log_text.config(state=tk.DISABLED)

    def clear_log(self):
        self.log_text.config(state=tk.NORMAL)
        self.log_text.delete(1.0, tk.END)
        self.log_text.config(state=tk.DISABLED)
        
    def set_status(self, text, color=None):
        if color:
            self.status_label.config(text=text, foreground=color)
        else:
            self.status_label.config(text=text, foreground=self.colors["text_main"])

    def update_speed_label(self, val):
        """Update speed limit label based on slider value."""
        speed = int(float(val))
        if speed == 0:
            self.speed_label.config(text="Unlimited")
        else:
            self.speed_label.config(text=f"{speed} KB/s")

    def start_translation(self):
        url = self.video_url.get().strip()
        video = self.video_path.get().strip()
        
        # Check if we have either a URL or a file
        if not url and (not video or not os.path.exists(video)):
            messagebox.showerror("Error", fix_text("Please enter a video URL or select a video file.\nأدخل رابط فيديو أو اختر ملف فيديو."))
            return

        self.is_running = True
        self.toggle_inputs(False)
        self.progress_bar.start(10)
        self.clear_log()
        
        # Prepare params
        target_code = vt.HELSINKI_LANGUAGES.get(self.target_lang.get(), "arb_Arab")
        batch = self.batch_size.get()
        keep = self.keep_audio.get()
        embed = self.embed_subs.get()
        out = self.output_path.get()
        prompt = self.initial_prompt.get().strip() or None
        speed = self.download_speed.get()
        quality = self.download_quality.get()
        profile = self.content_profile.get()
        vocal_isolation = self.use_vocal_isolation.get()
        download_only_mode = self.download_only.get()
        
        # Run in thread
        thread = threading.Thread(
            target=self.run_process, 
            args=(url, video, out, keep, batch, target_code, embed, prompt, speed, quality, profile, vocal_isolation, download_only_mode), 
            daemon=True
        )
        thread.start()

    def update_profile_description(self, event):
        """Update profile description label when selection changes."""
        profile_name = self.content_profile.get()
        profile = vt.CONTENT_PROFILES.get(profile_name, {})
        desc = profile.get("description", "")
        self.profile_desc_label.config(text=f"🎭 {desc}")

    def run_process(self, url, video, out, keep, batch, target_code, embed, initial_prompt=None, speed_limit=0, quality="720p", content_profile=None, use_vocal_isolation=False, download_only=False):
        # Redirect stdout
        class LogRedirector:
            def __init__(self, app): self.app = app
            def write(self, s): 
                if s.strip(): self.app.root.after(0, lambda: self.app.log(s.strip()))
            def flush(self): pass
            
        old_stdout = sys.stdout
        sys.stdout = LogRedirector(self)
        
        success = False
        try:
            # Download video from URL if provided
            if url:
                self.root.after(0, lambda: self.set_status(fix_text(f"جاري التحميل ({quality})... / Downloading..."), self.colors["primary"]))
                
                # Progress callback for download status
                def download_progress(status, percent, speed):
                    msg = f"Downloading ({quality}): {percent} @ {speed}"
                    self.root.after(0, lambda m=msg: self.set_status(m, self.colors["primary"]))
                
                # Determine output directory
                output_dir = Path(video).parent if video else Path.home() / "Downloads"
                
                # Download video
                downloaded_path = vt.download_video(
                    url=url,
                    output_dir=str(output_dir),
                    speed_limit=speed_limit if speed_limit > 0 else None,
                    quality=quality,
                    progress_callback=download_progress
                )
                
                if not downloaded_path:
                    print("❌ Download failed. Check the URL.")
                    self.root.after(0, lambda: self.on_complete(False))
                    return
                
                video = downloaded_path
                # Update video path in UI
                self.root.after(0, lambda: self.video_path.set(video))
                
                # Auto-set output SRT path
                if not out:
                    out = str(Path(video).with_suffix('')) + "_ar.srt"
                    self.root.after(0, lambda: self.output_path.set(out))
                
                # Download only mode - skip translation
                if download_only:
                    print("\n" + "=" * 60)
                    print("✅ DOWNLOAD COMPLETE!")
                    print("=" * 60)
                    print(f"📁 File: {video}")
                    self.root.after(0, lambda: self.on_complete(True))
                    return
            
            self.root.after(0, lambda: self.set_status(fix_text("جاري الترجمة... / Translating..."), self.colors["primary"]))
            
            # Run pipeline
            success = vt.process_video(
                video_path=video,
                output_srt=out or None,
                keep_audio=keep,
                batch_size=batch,
                target_lang=target_code,
                initial_prompt=initial_prompt,
                content_profile=content_profile,
                use_vocal_isolation=use_vocal_isolation
            )
            
            # Embed if requested (Note: vt.process_video doesn't do embedding, main logic does.
            # We need to replicate embedding logic here if we wanted it, but let's stick to core translation
            # Update: I see process_video returns boolean. Embedding was in main().
            # I will add embedding logic here quickly.
            
            if success and embed:
                print("Triggering embedding process (FAST MUXING)...")
                
                # بناء مسارات الملفات
                srt_path = out if out else str(Path(video).with_suffix('')) + f"_{target_code[:2]}.srt"
                # تأكد أن الامتداد mp4 للحاوية
                output_video = str(Path(video).with_suffix('')) + "_subtitled.mp4"
                
                # التحقق من وجود ملف الترجمة قبل البدء
                if not os.path.exists(srt_path):
                     # محاولة ذكية لإيجاد الملف إذا اختلف الاسم قليلاً
                     srt_path = str(Path(video).parent / (Path(video).stem + "_ar.srt"))
                
                # ---------------------------------------------------------
                # ENGINEERING FIX: Switch from Transcoding to Muxing
                # Old (Slow): "-vf", f"subtitles={srt_path}"
                # New (Fast): "-c", "copy", "-c:s", "mov_text"
                # ---------------------------------------------------------
                cmd = [
                    "ffmpeg", "-y",
                    "-i", video,             # Input Video
                    "-i", srt_path,          # Input Subtitle
                    "-c", "copy",            # Copy Video/Audio streams directly (0% CPU)
                    "-c:s", "mov_text",      # Convert SRT to MP4 Subtitle Track
                    "-metadata:s:s:0", "language=ara", # Set language tag
                    output_video
                ]
                
                print(f"🚀 Running fast muxing: {' '.join(cmd)}")
                import subprocess
                # نستخدم capture_output=False لنرى أي خطأ من ffmpeg مباشرة
                subprocess.run(cmd, check=True, capture_output=False)
                print(f"✅ Video created instantly: {output_video}")

        except Exception as e:
            print(f"Critical Error: {e}")
            success = False
        finally:
            sys.stdout = old_stdout
            self.root.after(0, lambda: self.on_complete(success))

    def on_complete(self, success):
        self.is_running = False
        self.toggle_inputs(True)
        self.progress_bar.stop()
        
        if success:
            self.set_status("Operation Complete Successfully!", self.colors["success"])
            # Load SRT into editor if available
            srt_path = self.output_path.get() or str(Path(self.video_path.get()).with_suffix('')) + "_ar.srt"
            if os.path.exists(srt_path):
                self.load_srt_to_editor(srt_path)
                messagebox.showinfo("Done", f"Processing complete!\n\nSRT saved to:\n{srt_path}\n\nClick 'Open Editor' to review and edit.")
            else:
                messagebox.showinfo("Done", "Video processing completed successfully!")
        else:
            self.set_status("Operation Failed", self.colors["error"])
            messagebox.showerror("Error", "Something went wrong. Check logs.")
    
    def load_srt_to_editor(self, srt_path, original_segments=None):
        """Parse SRT file and load segments into editor.
        
        Args:
            srt_path: Path to translated SRT file
            original_segments: Optional list of original transcribed segments
        """
        self.segments_data = []
        self.current_srt_path = srt_path
        
        try:
            with open(srt_path, 'r', encoding='utf-8') as f:
                content = f.read()
            
            import re
            # Parse SRT format
            pattern = r'(\d+)\n(\d{2}:\d{2}:\d{2},\d{3}) --> (\d{2}:\d{2}:\d{2},\d{3})\n(.+?)(?=\n\n|\Z)'
            matches = re.findall(pattern, content, re.DOTALL)
            
            # Try to load original segments from journal if available
            if original_segments is None:
                # Try to find original transcription from journal
                try:
                    from journal import TranscriptionJournal
                    video_path = str(Path(srt_path).with_suffix('.mp4'))
                    if not os.path.exists(video_path):
                        video_path = str(Path(srt_path).with_suffix('.mkv'))
                    if os.path.exists(video_path):
                        journal = TranscriptionJournal(video_path)
                        if journal.has_checkpoint():
                            original_segments = journal.get_transcribed_segments()
                            self.log(f"📂 Loaded {len(original_segments)} original segments from journal")
                except Exception as e:
                    self.log(f"Note: Could not load original text ({e})")
            
            for i, match in enumerate(matches):
                idx, start, end, text = match
                
                # Get original text if available
                original = ''
                if original_segments and i < len(original_segments):
                    original = original_segments[i].get('text', '')
                
                self.segments_data.append({
                    'idx': int(idx),
                    'start': start,
                    'end': end,
                    'original': original,
                    'text': text.strip()
                })
            
            self.log(f"Loaded {len(self.segments_data)} segments from SRT")
            
        except Exception as e:
            self.log(f"Error loading SRT: {e}")
    
    def show_editor(self):
        """Open editor window for subtitle verification and editing."""
        if not self.segments_data:
            # Try to load from current output path
            srt_path = self.output_path.get()
            if srt_path and os.path.exists(srt_path):
                self.load_srt_to_editor(srt_path)
            else:
                messagebox.showwarning("No Data", "No subtitle data to edit.\nProcess a video first or select an SRT file.")
                return
        
        # Create editor window
        editor = tk.Toplevel(self.root)
        editor.title(fix_text("Subtitle Editor / محرر الترجمة"))
        editor.geometry("1000x600")
        editor.minsize(800, 400)
        
        # Apply theme to editor
        editor.configure(bg=self.colors["bg_main"])
        
        # Header
        header_frame = ttk.Frame(editor, padding="10")
        header_frame.pack(fill=tk.X)
        
        ttk.Label(header_frame, text=fix_text("Edit Subtitles / تعديل الترجمة"), 
                  style="Header.TLabel").pack(side=tk.LEFT)
        
        if self.current_srt_path:
            ttk.Label(header_frame, text=f"File: {Path(self.current_srt_path).name}", 
                      style="SubLabel.TLabel").pack(side=tk.RIGHT)
        
        # Treeview with scrollbars
        tree_frame = ttk.Frame(editor, padding="10")
        tree_frame.pack(fill=tk.BOTH, expand=True)
        
        # Scrollbars
        vsb = ttk.Scrollbar(tree_frame, orient="vertical")
        hsb = ttk.Scrollbar(tree_frame, orient="horizontal")
        
        # Treeview
        columns = ("idx", "start", "end", "original", "text")
        tree = ttk.Treeview(tree_frame, columns=columns, show="headings",
                           yscrollcommand=vsb.set, xscrollcommand=hsb.set)
        
        # Configure scrollbars
        vsb.config(command=tree.yview)
        hsb.config(command=tree.xview)
        
        # Column headings
        tree.heading("idx", text="#")
        tree.heading("start", text=fix_text("Start / البداية"))
        tree.heading("end", text=fix_text("End / النهاية"))
        tree.heading("original", text=fix_text("Original / النص الأصلي"))
        tree.heading("text", text=fix_text("Translated / المترجم"))
        
        # Column widths
        tree.column("idx", width=40, anchor="center")
        tree.column("start", width=90, anchor="center")
        tree.column("end", width=90, anchor="center")
        tree.column("original", width=350, anchor="w")
        tree.column("text", width=350, anchor="w")
        
        # Grid layout
        tree.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")
        hsb.grid(row=1, column=0, sticky="ew")
        
        tree_frame.columnconfigure(0, weight=1)
        tree_frame.rowconfigure(0, weight=1)
        
        # Populate treeview
        for seg in self.segments_data:
            original = seg.get('original', '')
            tree.insert("", "end", values=(seg['idx'], seg['start'], seg['end'], original, seg['text']))
        
        # Edit functionality
        def on_double_click(event):
            item = tree.selection()[0] if tree.selection() else None
            if not item:
                return
            
            column = tree.identify_column(event.x)
            col_idx = int(column.replace('#', '')) - 1
            
            if col_idx != 4:  # Only allow editing translated text column (index 4)
                return
            
            # Get current value
            values = tree.item(item, 'values')
            original_text = values[3]  # Original text
            current_text = values[4]   # Translated text
            
            # Create edit dialog
            edit_dialog = tk.Toplevel(editor)
            edit_dialog.title(fix_text("Edit Subtitle / تعديل الترجمة"))
            edit_dialog.geometry("600x250")
            edit_dialog.transient(editor)
            edit_dialog.grab_set()
            
            ttk.Label(edit_dialog, text=f"Segment {values[0]} ({values[1]} → {values[2]})").pack(pady=5)
            
            # Show original text (read-only)
            orig_frame = ttk.Frame(edit_dialog)
            orig_frame.pack(fill=tk.X, padx=10, pady=5)
            ttk.Label(orig_frame, text=fix_text("Original / الأصلي:"), font=("Helvetica", 9, "bold")).pack(anchor="w")
            orig_label = ttk.Label(orig_frame, text=original_text, wraplength=550, foreground="gray")
            orig_label.pack(anchor="w", pady=2)
            
            # Editable translated text
            trans_frame = ttk.Frame(edit_dialog)
            trans_frame.pack(fill=tk.X, padx=10, pady=5)
            ttk.Label(trans_frame, text=fix_text("Translated / المترجم:"), font=("Helvetica", 9, "bold")).pack(anchor="w")
            text_var = tk.StringVar(value=current_text)
            entry = ttk.Entry(trans_frame, textvariable=text_var, width=70)
            entry.pack(fill=tk.X, pady=2)
            entry.focus_set()
            entry.select_range(0, tk.END)
            
            def save_edit():
                new_text = text_var.get()
                tree.item(item, values=(values[0], values[1], values[2], values[3], new_text))
                # Update internal data
                idx = int(values[0]) - 1
                if 0 <= idx < len(self.segments_data):
                    self.segments_data[idx]['text'] = new_text
                edit_dialog.destroy()
            
            def cancel_edit():
                edit_dialog.destroy()
            
            btn_frame = ttk.Frame(edit_dialog)
            btn_frame.pack(pady=10)
            ttk.Button(btn_frame, text="Save", command=save_edit).pack(side=tk.LEFT, padx=5)
            ttk.Button(btn_frame, text="Cancel", command=cancel_edit).pack(side=tk.LEFT, padx=5)
            
            entry.bind('<Return>', lambda e: save_edit())
            entry.bind('<Escape>', lambda e: cancel_edit())
        
        tree.bind('<Double-1>', on_double_click)
        
        # Action buttons
        btn_frame = ttk.Frame(editor, padding="10")
        btn_frame.pack(fill=tk.X)
        
        def save_srt():
            if not self.current_srt_path:
                path = filedialog.asksaveasfilename(
                    title="Save SRT",
                    filetypes=[("Subtitle", "*.srt")],
                    defaultextension=".srt"
                )
                if not path:
                    return
                self.current_srt_path = path
            
            try:
                with open(self.current_srt_path, 'w', encoding='utf-8') as f:
                    for seg in self.segments_data:
                        f.write(f"{seg['idx']}\n")
                        f.write(f"{seg['start']} --> {seg['end']}\n")
                        f.write(f"{seg['text']}\n\n")
                
                messagebox.showinfo("Saved", f"SRT saved to:\n{self.current_srt_path}")
                self.log(f"SRT saved: {self.current_srt_path}")
                
            except Exception as e:
                messagebox.showerror("Error", f"Failed to save: {e}")
        
        def load_srt():
            path = filedialog.askopenfilename(
                title="Open SRT",
                filetypes=[("Subtitle", "*.srt"), ("All Files", "*.*")]
            )
            if path:
                self.load_srt_to_editor(path)
                # Refresh treeview
                tree.delete(*tree.get_children())
                for seg in self.segments_data:
                    original = seg.get('original', '')
                    tree.insert("", "end", values=(seg['idx'], seg['start'], seg['end'], original, seg['text']))
        
        ttk.Button(btn_frame, text=fix_text("💾 Save SRT / حفظ"), style="Success.TButton", 
                   command=save_srt).pack(side=tk.LEFT, padx=5)
        ttk.Button(btn_frame, text=fix_text("📂 Load SRT / فتح"), command=load_srt).pack(side=tk.LEFT, padx=5)
        ttk.Button(btn_frame, text=fix_text("Close / إغلاق"), command=editor.destroy).pack(side=tk.RIGHT, padx=5)
        
        # Stats label
        ttk.Label(btn_frame, text=f"Total segments: {len(self.segments_data)}", 
                  style="SubLabel.TLabel").pack(side=tk.RIGHT, padx=20)

    def stop_translation(self):
        # Note: True stopping requires multiprocessing or complex flag checking in logic
        # For now we just flag it
        self.log("Stop requested (Processes may take time to finish)...")
        self.is_running = False # Logic needs to check this

    def toggle_inputs(self, enable):
        state = tk.NORMAL if enable else tk.DISABLED
        self.start_btn.config(state=state)
        self.stop_btn.config(state=tk.NORMAL if not enable else tk.DISABLED)
        # We could disable entries too, but leaving them readable is fine

def main():
    root = tk.Tk()
    # High DPI Support
    try:
        root.tk.call('tk', 'scaling', 1.5)
    except:
        pass
    app = VideoTranslatorGUI(root)
    root.mainloop()

if __name__ == "__main__":
    main()
